1	// The one place this repo talks to the Cloudflare Email Service. Every sender goes
2	// through `sendEmail`; the `email-service-single-client` declared check beside this
3	// file is what keeps that true, because the API's constraints are only worth
4	// encoding once and a second caller with its own fetch would encode none of them.
5	//
6	// The REST surface is documented at
7	// https://developers.cloudflare.com/email-service/api/send-emails/rest-api/ and its
8	// header rules at https://developers.cloudflare.com/email-service/reference/headers/.
9	// `validateMessage` below is those two pages' ceilings and allowlists, applied before
10	// the request rather than after: the service rejects the WHOLE send on a single bad
11	// header, so a message that would be refused is worth catching where the reason is
12	// still in front of whoever wrote it.
13	
14	const API_BASE = 'https://api.cloudflare.com/client/v4';
15	
16	// Every ceiling here is from the platform limits page
17	// (https://developers.cloudflare.com/email-service/platform/limits/), except the two
18	// header counts, which are the headers reference's own table.
19	export const MAX_RECIPIENTS = 50; // combined across to, cc and bcc
20	export const MAX_SUBJECT_CHARS = 998;
21	export const MAX_MESSAGE_BYTES = 5 * 1024 * 1024;
22	export const MAX_HEADER_NAME_BYTES = 100;
23	export const MAX_HEADER_VALUE_BYTES = 2048;
24	export const MAX_HEADERS_PAYLOAD_BYTES = 16 * 1024;
25	export const MAX_ALLOWLISTED_HEADERS = 20;
26	
27	// The headers reference's allowlist, canonical casing, matched case-insensitively.
28	// Anything not here and not `X-` prefixed is rejected by the API with
29	// E_HEADER_NOT_ALLOWED — and the rejection is of the whole message, not the header.
30	export const ALLOWLISTED_HEADERS = [
31	  'In-Reply-To', 'References', 'Thread-Index', 'Thread-Topic',
32	  'List-Unsubscribe', 'List-Unsubscribe-Post', 'List-Id', 'List-Archive', 'List-Help',
33	  'List-Owner', 'List-Post', 'List-Subscribe', 'Precedence',
34	  'Auto-Submitted',
35	  'Content-Language', 'Keywords', 'Comments', 'Importance', 'Priority', 'Sensitivity',
36	  'Organization',
37	  'Require-Recipient-Valid-Since', 'Expires', 'Reply-By',
38	  'Archived-At',
39	];
40	
41	// Set by the platform, or owned by a first-class API field. Either way the API
42	// refuses the send when one appears in `headers`; they are listed apart because the
43	// fix differs — drop it, versus move it to its own field.
44	const PLATFORM_HEADERS = [
45	  'Date', 'Message-ID', 'MIME-Version', 'Content-Type', 'Content-Transfer-Encoding',
46	  'DKIM-Signature', 'Return-Path', 'Received', 'Feedback-ID', 'TLS-Required',
47	  'TLS-Report-Domain', 'TLS-Report-Submitter', 'CFBL-Address', 'CFBL-Feedback-ID',
48	];
49	const API_FIELD_HEADERS = ['From', 'To', 'Cc', 'Bcc', 'Subject', 'Reply-To'];
50	
51	// The error codes that mean a PERSON has something to change — a token scope, an
52	// entitlement, a zone setting — as opposed to a request this code got wrong or a
53	// service having a bad minute. `sendEmail` throws with `needsAction` set from this
54	// set, and a task worker routes its park by it.
55	const NEEDS_ACTION_CODES = new Set([
56	  // Cloudflare's own global code, raised by the API gateway before any Email Service
57	  // handler runs, and so the one an unscoped token is actually refused with: a send on
58	  // a token minted for another product came back `10000 Authentication error` rather
59	  // than the 10102 the Email Service would have given.
60	  10000, // Authentication error — token missing, invalid, or without the sending scope
61	  10101, // authentication.unauthorized — missing or invalid token
62	  10102, // authentication.forbidden — token lacks permission to send
63	  10103, // authentication.bad_token_type
64	  10105, // authentication.not_entitled — account not entitled to Email Sending
65	  10203, // email.sending_disabled — sending disabled for this zone or account
66	]);
67	
68	export class EmailSendError extends Error {
69	  constructor(message, { needsAction = false } = {}) {
70	    super(message);
71	    this.name = 'EmailSendError';
72	    this.needsAction = needsAction;
73	  }
74	}
75	
76	const bytes = (s) => Buffer.byteLength(String(s), 'utf8');
77	const asList = (v) => (v == null ? [] : Array.isArray(v) ? v : [v]);
78	// A recipient is a bare address or `{ address, name }` — the REST spelling. The
79	// Workers binding's `{ email, name }` is a different API and is what
80	// `email-service-rest-field-spellings` watches for.
81	const addressOf = (r) => (typeof r === 'string' ? r : r?.address);
82	
83	// Everything the API would reject, as a list of reasons. Empty means the message is
84	// within every documented ceiling — not that it will deliver, which is the
85	// recipient's domain's call.
86	export function validateMessage(message) {
87	  const problems = [];
88	  const { from, to, cc, bcc, subject, html, text, headers } = message ?? {};
89	
90	  if (!addressOf(from)) problems.push('no `from` address');
91	  const recipients = [...asList(to), ...asList(cc), ...asList(bcc)];
92	  if (!recipients.length) problems.push('no recipients');
93	  if (recipients.length > MAX_RECIPIENTS) {
94	    problems.push(`${recipients.length} recipients across to/cc/bcc, over the limit of ${MAX_RECIPIENTS}`);
95	  }
96	  for (const r of recipients) if (!addressOf(r)) problems.push(`a recipient carries no address: ${JSON.stringify(r)}`);
97	
98	  if (!subject) problems.push('no `subject`');
99	  else if (String(subject).length > MAX_SUBJECT_CHARS) {
100	    problems.push(`subject is ${String(subject).length} characters, over the limit of ${MAX_SUBJECT_CHARS}`);
101	  }
102	  // Both bodies, always: a mail client with HTML off shows the `text` part, and a
103	  // send carrying only HTML reads as bulk to the filters that grade it.
104	  if (!html && !text) problems.push('no `html` and no `text` body');
105	  else if (html && !text) problems.push('an `html` body with no `text` alternative');
106	
107	  problems.push(...headerProblems(headers));
108	
109	  const size = bytes(JSON.stringify(message ?? {}));
110	  if (size > MAX_MESSAGE_BYTES) {
111	    problems.push(`the message is ${size} bytes, over the limit of ${MAX_MESSAGE_BYTES}`);
112	  }
113	  return problems;
114	}
115	
116	function headerProblems(headers) {
117	  if (!headers) return [];
118	  const problems = [];
119	  const allowed = new Map(ALLOWLISTED_HEADERS.map((h) => [h.toLowerCase(), h]));
120	  const platform = new Set(PLATFORM_HEADERS.map((h) => h.toLowerCase()));
121	  const apiField = new Map(API_FIELD_HEADERS.map((h) => [h.toLowerCase(), h]));
122	  let allowlisted = 0;
123	  let payload = 0;
124	
125	  for (const [name, value] of Object.entries(headers)) {
126	    const key = name.toLowerCase();
127	    payload += bytes(name) + 2 + bytes(value ?? '') + 2;
128	    if (bytes(name) > MAX_HEADER_NAME_BYTES) problems.push(`header \`${name}\` has a name over ${MAX_HEADER_NAME_BYTES} bytes`);
129	    if (bytes(value ?? '') > MAX_HEADER_VALUE_BYTES) problems.push(`header \`${name}\` has a value over ${MAX_HEADER_VALUE_BYTES} bytes`);
130	    if (!String(value ?? '').length) problems.push(`header \`${name}\` has an empty value`);
131	    if (/[\r\n]/.test(String(value ?? ''))) problems.push(`header \`${name}\` has a value carrying a bare CR or LF`);
132	
133	    if (platform.has(key)) {
134	      problems.push(`header \`${name}\` is set by the platform and cannot be sent`);
135	    } else if (apiField.has(key)) {
136	      problems.push(`header \`${name}\` belongs in its own API field, not in \`headers\``);
137	    } else if (key.startsWith('x-')) {
138	      if (!/^X-[A-Za-z0-9\-_]+$/.test(name)) problems.push(`header \`${name}\` is not a valid X- header name`);
139	    } else if (allowed.has(key)) {
140	      allowlisted += 1;
141	      // The one allowlisted header whose VALUE the API pins: RFC 8058 one-click.
142	      if (key === 'list-unsubscribe-post' && value !== 'List-Unsubscribe=One-Click') {
143	        problems.push('header `List-Unsubscribe-Post` must be exactly `List-Unsubscribe=One-Click`');
144	      }
145	      if (key === 'list-unsubscribe' && !/<(https|mailto):/.test(String(value))) {
146	        problems.push('header `List-Unsubscribe` must carry an angle-bracketed https: or mailto: URI');
147	      }
148	    } else {
149	      problems.push(`header \`${name}\` is not on the allowlist and is not an X- header`);
150	    }
151	  }
152	
153	  if (allowlisted > MAX_ALLOWLISTED_HEADERS) {
154	    problems.push(`${allowlisted} allowlisted headers, over the limit of ${MAX_ALLOWLISTED_HEADERS}`);
155	  }
156	  if (payload > MAX_HEADERS_PAYLOAD_BYTES) {
157	    problems.push(`the custom headers total ${payload} bytes, over the limit of ${MAX_HEADERS_PAYLOAD_BYTES}`);
158	  }
159	  return problems;
160	}
161	
162	// The API's own numeric codes, rendered as the sentence a park is worth reading. The
163	// codes themselves say nothing about where the fix lives — "Authentication error" reads
164	// as a worker bug — so a needs-action refusal carries the three settings that produce
165	// one, which is what the reader of a park has to go and check.
166	const NEEDS_ACTION_REMEDY = 'a Cloudflare-side setting rather than the message: the token\'s Email '
167	  + 'Sending permission, the account\'s entitlement to send, or the zone\'s sending switch';
168	
169	function apiFailure(status, body) {
170	  const errors = Array.isArray(body?.errors) ? body.errors : [];
171	  const needsAction = errors.some((e) => NEEDS_ACTION_CODES.has(e?.code));
172	  const detail = errors.length
173	    ? errors.map((e) => `${e.code} ${e.message}`).join('; ')
174	    : `HTTP ${status}`;
175	  return new EmailSendError(
176	    `the Email Service refused the send: ${detail}${needsAction ? ` — ${NEEDS_ACTION_REMEDY}` : ''}`,
177	    { needsAction },
178	  );
179	}
180	
181	// Sends one message and returns the API's recipient-grouped result. `fetchImpl` is a
182	// seam for the tests: nothing else passes it.
183	export async function sendEmail({ accountId, token, message, fetchImpl = fetch }) {
184	  if (!accountId) throw new EmailSendError('no Cloudflare account id', { needsAction: true });
185	  if (!token) throw new EmailSendError('no Cloudflare API token', { needsAction: true });
186	
187	  const problems = validateMessage(message);
188	  if (problems.length) {
189	    throw new EmailSendError(`the message would be refused: ${problems.join('; ')}`);
190	  }
191	
192	  const response = await fetchImpl(`${API_BASE}/accounts/${accountId}/email/sending/send`, {
193	    method: 'POST',
194	    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
195	    body: JSON.stringify(message),
196	  });
197	
198	  // A non-JSON body is a proxy or an outage answering, not the API; say what came
199	  // back rather than throw a parse error nobody can act on.
200	  let body = null;
201	  try { body = await response.json(); } catch { /* handled below */ }
202	  if (!response.ok || body?.success !== true) throw apiFailure(response.status, body);
203	
204	  const result = body.result ?? {};
205	  // A permanent bounce is an accepted request that delivered to nobody. Before a
206	  // sending domain is onboarded the only deliverable recipients are the account's
207	  // verified destination addresses, so this is the shape an unverified recipient
208	  // takes — a person's to fix, not a retry.
209	  const bounced = asList(result.permanent_bounces);
210	  if (bounced.length && !asList(result.delivered).length && !asList(result.queued).length) {
211	    throw new EmailSendError(
212	      `every recipient permanently bounced: ${bounced.join(', ')} — the address must be a verified `
213	      + 'destination address until a sending domain is onboarded',
214	      { needsAction: true },
215	    );
216	  }
217	  return result;
218	}
219

