const cases = [
  ["git mv .claudinite/pending-workflows/foo.yml .github/workflows/foo.yml", true],
  ["git mv -f .claudinite/pending-workflows/foo.yml .github/workflows/foo.yml", false],
  ["cp -f .claudinite/pending-workflows/foo.yml .github/workflows/foo.yml && rm .claudinite/pending-workflows/foo.yml", false],
  ["git mv old-name.mjs new-name.mjs", false],
