3	import { fileURLToPath } from 'node:url';
4	import { dirname, join } from 'node:path';
5	import { loadDeclaredChecks, guardFindings } from
6	  '../../../../shared/engine/checks/helpers/pattern-rules.mjs';
7	
8	const packDir = join(dirname(fileURLToPath(import.meta.url)), '..');
9	const rules = loadDeclaredChecks(packDir);
10	const rule = rules.find((r) => r.id === 'branch-from-local-main');
11	
12	test('branch-from-local-main fires on a bare local-main branch, stays quiet on origin/main', () => {
13	  assert.ok(rule, 'branch-from-local-main is declared in the pack');
14	
15	  const call = (command) => ({ name: 'Bash', input: { command } });
16	
17	  assert.equal(guardFindings(rule, call('git checkout -b claude/foo main')).length, 1);
18	  assert.equal(guardFindings(rule, call('git branch claude/foo main')).length, 1);
19	
20	  assert.equal(guardFindings(rule, call('git fetch origin main && git checkout -b claude/foo origin/main')).length, 0);
21	  assert.equal(guardFindings(rule, call('git checkout main')).length, 0);
22	  assert.equal(guardFindings(rule, call('git status')).length, 0);
23	});
